import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;

public class ContentLengthFramerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String visible(String text) {
        return text.replace("\r", "\\r").replace("\n", "\\n");
    }

    static String sentBytes(String body) {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        try {
            ContentLengthFramer.sendFramed(buf, body);
        } catch (IOException e) {
            return "IOException";
        }
        return visible(new String(buf.toByteArray(), StandardCharsets.UTF_8));
    }

    static byte[] frameOf(String body) {
        byte[] payload = body.getBytes(StandardCharsets.UTF_8);
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        byte[] head = ("Content-Length: " + payload.length + "\r\n\r\n")
                .getBytes(StandardCharsets.UTF_8);
        buf.write(head, 0, head.length);
        buf.write(payload, 0, payload.length);
        return buf.toByteArray();
    }

    /** Echoes one framed message back, uppercased, over a loopback socket. */
    static String roundTrip(String body) {
        ServerSocket server = null;
        Thread serverThread = null;
        Socket client = null;
        try {
            server = new ServerSocket(0, 4, InetAddress.getByName("127.0.0.1"));
            final ServerSocket listening = server;
            serverThread = new Thread(() -> {
                Socket peer = null;
                try {
                    listening.setSoTimeout(2000);
                    peer = listening.accept();
                    peer.setSoTimeout(2000);
                    String request = ContentLengthFramer.readFramed(peer.getInputStream());
                    ContentLengthFramer.sendFramed(peer.getOutputStream(),
                            request.toUpperCase(java.util.Locale.ROOT));
                } catch (Exception ignored) {
                    // the client will report the missing reply
                } finally {
                    if (peer != null) {
                        try {
                            peer.close();
                        } catch (IOException ignored) {
                            // nothing useful to do
                        }
                    }
                }
            });
            serverThread.setDaemon(true);
            serverThread.start();

            client = new Socket();
            client.connect(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),
                    server.getLocalPort()), 2000);
            client.setSoTimeout(2000);
            ContentLengthFramer.sendFramed(client.getOutputStream(), body);
            return ContentLengthFramer.readFramed(client.getInputStream());
        } catch (Exception e) {
            return "no reply: " + e.getClass().getSimpleName();
        } finally {
            if (client != null) {
                try {
                    client.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
            if (serverThread != null) {
                try {
                    serverThread.join(3000);
                } catch (InterruptedException ignored) {
                    Thread.currentThread().interrupt();
                }
            }
            if (server != null) {
                try {
                    server.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
        }
    }

    public static void main(String[] args) {
        check("sendFramed writes header, blank line and body",
                "Content-Length: 5\\r\\n\\r\\nhello", sentBytes("hello"));
        check("an empty body is still framed",
                "Content-Length: 0\\r\\n\\r\\n", sentBytes(""));
        check("the length counts BYTES, not characters",
                "Content-Length: 5\\r\\n\\r\\ncaf\u00e9", sentBytes("caf\u00e9"));

        try {
            check("readFramed reads a whole message", "hello",
                    ContentLengthFramer.readFramed(new ByteArrayInputStream(frameOf("hello"))));
            check("readFramed handles an empty body", "",
                    ContentLengthFramer.readFramed(new ByteArrayInputStream(frameOf(""))));
            check("readFramed rebuilds multi-byte text", "caf\u00e9",
                    ContentLengthFramer.readFramed(new ByteArrayInputStream(frameOf("caf\u00e9"))));

            byte[] frame = frameOf("hello");
            byte[] withExtra = new byte[frame.length + 1];
            System.arraycopy(frame, 0, withExtra, 0, frame.length);
            withExtra[frame.length] = (byte) 'X';
            InputStream stream = new ByteArrayInputStream(withExtra);
            ContentLengthFramer.readFramed(stream);
            check("readFramed stops after exactly N bytes", 88, stream.read());
        } catch (IOException e) {
            System.out.println("FAIL  readFramed threw -- " + e);
            failures++;
        }

        check("a framed message survives a loopback round trip", "HELLO SOCKETS",
                roundTrip("hello sockets"));
        check("multi-byte text survives the round trip", "CAF\u00c9", roundTrip("caf\u00e9"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
        System.exit(0);
    }
}

