import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

/**
 * TASK: Frame messages on a stream with a Content-Length header.
 *
 * A stream has no message boundaries, so a length header tells the reader
 * exactly how many bytes belong to this message.
 *
 * sendFramed(out, body) writes, in UTF-8:
 *     "Content-Length: " + byteLength + "\r\n\r\n" + the body bytes
 * and then flushes. byteLength is the number of UTF-8 BYTES, which is not the
 * same as body.length() once a character needs more than one byte.
 *
 * readFramed(in):
 *   1. read ONE BYTE AT A TIME until the four-byte sequence \r\n\r\n has been
 *      seen -- do NOT wrap the stream in a BufferedReader, because that would
 *      read ahead and swallow bytes belonging to the next message,
 *   2. parse the number out of the "Content-Length: N" header,
 *   3. read EXACTLY that many bytes (in.read may return fewer than you asked
 *      for, so loop until you have them all),
 *   4. return those bytes decoded as UTF-8.
 *   If the stream ends early, throw new EOFException("stream ended early").
 *
 * Example: sendFramed writes "Content-Length: 5\r\n\r\nhello", and readFramed
 * on that stream returns "hello" while leaving anything after it untouched.
 */
public class ContentLengthFramer {

    public static void sendFramed(OutputStream out, String body) throws IOException {
        byte[] payload = body.getBytes(StandardCharsets.UTF_8);
        out.write(("Content-Length: " + payload.length + "\r\n\r\n")
                .getBytes(StandardCharsets.UTF_8));
        out.write(payload);
        out.flush();
    }

    public static String readFramed(InputStream in) throws IOException {
        StringBuilder header = new StringBuilder();
        while (!header.toString().endsWith("\r\n\r\n")) {
            int next = in.read();
            if (next < 0) {
                throw new EOFException("stream ended early");
            }
            header.append((char) next);
        }

        String headerText = header.toString().trim();
        int colon = headerText.indexOf(':');
        int length = Integer.parseInt(headerText.substring(colon + 1).trim());

        byte[] body = new byte[length];
        int filled = 0;
        while (filled < length) {
            int read = in.read(body, filled, length - filled);
            if (read < 0) {
                throw new EOFException("stream ended early");
            }
            filled += read;
        }
        return new String(body, StandardCharsets.UTF_8);
    }
}
